WITH flattened_attrs AS (SELECT id, effective_from, currency, tier_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT DATE_TRUNC('YEAR', effective_from) AS year_start, ROUND(AVG(lowest_price), 2) AS avg_lowest_price, COUNT(CASE WHEN currency = 'EUR' THEN 1 END) AS eur_count FROM flattened_attrs GROUP BY DATE_TRUNC('YEAR', effective_from);
